package com.pvp.travelmatch.repository; import com.pvp.travelmatch.entity.ProfileView; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDateTime; import java.util.*; public interface ProfileViewRepository extends JpaRepository<ProfileView,Long>{ Optional<ProfileView> findByViewerIdAndViewedUserId(Long viewerId, Long viewedId); List<ProfileView> findByViewedUserIdOrderByViewedAtDesc(Long viewedId, Pageable p); @Query("select p from ProfileView p where p.viewer.id=:viewerId and p.viewedUser.id=:viewedId and p.viewedAt>:since") Optional<ProfileView> findRecent(@Param("viewerId")Long viewerId, @Param("viewedId")Long viewedId, @Param("since")LocalDateTime since); }
